css:
.inv-title {
  text-align: center;
  font-size: 13pt;
  font-weight: bold;
  margin-bottom: 15px;
  font-family: 'InterVariable', system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
table.inv {
  width: 100%;
  border-collapse: collapse;
  margin-top: 10px;
  font-family: 'InterVariable', system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
table.inv th, table.inv td {
  border: 1px solid #000;
  padding: 5px;
  font-size: 10pt;
}
.row { margin-top: 4px; }
.sign { margin-top: 40px; }

@media print {
  @page { margin: 15mm; }
}

body, .inv-title, table.inv, table.inv th, table.inv td, .row, .sign {
  font-family: "Times New Roman", Times, serif;
  line-height: 1.2;               /* стабільніша висота рядка */
  -webkit-text-size-adjust: 100%;
}
table.inv { table-layout: fixed; } /* менше “стрибків” колонок */

.print-format, 
.print-format * {
  font-family: "Times New Roman", Times, serif !important;
  line-height: 1.2;
}

html:
{%- set assets = frappe.get_all(
    "oiAsset",
    filters={"location": doc.name},
    fields=["inventory_no","asset_name","serial_no","responsible_employee","status","quantity"],
    order_by="asset_name asc"
) -%}

{%- macro person_name(ref) -%}
  {%- if not ref -%}-{% else -%}
    {%- set nm = frappe.db.get_value("oiEmployee", ref, "full_name") -%}
    {{ nm or frappe.db.get_value("User", ref, "full_name") or ref }}
  {%- endif -%}
{%- endmacro -%}

{%- macro fmt_qty(v) -%}
  {%- if v is not none -%}
    {%- set s = ("%.2f"|format(v)).rstrip('0').rstrip('.') -%}
    {{ s }}
  {%- else -%}-{% endif -%}
{%- endmacro -%}

{%- set ns = namespace(total_qty=0) -%}

<div class="inv-title">ОПИС МАЙНА КАБІНЕТА № {{ doc.room }}</div>

<div class="row">Адреса: {{ doc.building }}, поверх {{ doc.floor or "-" }}</div>
<div class="row">
  Відповідальний по кабінету:
  <b>{{ doc.responsible_name or "-" }}</b>{% if doc.responsible_phone %} ({{ doc.responsible_phone }}){% endif %}
</div>

<table class="inv">
  <thead>
    <tr>
      <th style="width:25px;">№</th>
      <th>Найменування</th>
      <th style="width:50px;">Од.<br/>виміру</th>
      <th style="width:60px;">К-сть</th>
      <th style="width:100px;">Інвентарний<br/>номер</th>
      <th style="width:120px;">Серійний №</th>
      <th style="width:140px;">Відповідальний<br/>(МВО)</th>
    </tr>
  </thead>
  <tbody>
    {% for a in assets %}
    {# підсумовуємо кількість #}
    {%- set ns.total_qty = ns.total_qty + (a.quantity or 0) -%}
    <tr>
      <td>{{ loop.index }}</td>
      <td>{{ a.asset_name }}</td>
      <td>шт.</td>
      <td>{{ fmt_qty(a.quantity) }}</td>
      <td>{{ a.inventory_no or "-" }}</td>
      <td>{{ a.serial_no or "-" }}</td>
      <td>{{ person_name(a.responsible_employee) }}</td>
    </tr>
    {% else %}
    <tr><td colspan="7" style="text-align:center;">Немає активів у кабінеті</td></tr>
    {% endfor %}
  </tbody>

  {# Підсумок по кількості (опціонально, можна прибрати) #}
  {% if assets and assets|length > 0 %}
  <tfoot>
    <tr>
      <th colspan="3" style="text-align:right;">Разом:</th>
      <th>{{ fmt_qty(ns.total_qty) }}</th>
      <th colspan="3"></th>
    </tr>
  </tfoot>
  {% endif %}
</table>

<div class="sign">Підпис відповідального по кабінету: ___________________</div>
